css:
@font-face {
	font-family: "THSarabun";
	src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf");
}

@page {
	size: A4 portrait;
	margin: 0;
}

* {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}

html,
body {
	margin: 0;
	padding: 0;
}

body {
	font-family:
		"Sarabun", "TH Sarabun New", "Noto Sans Thai", "THSarabun", Arial,
		sans-serif;
	font-size: 12pt;
	color: #111;
}

.print-format,
.print-format-preview {
	padding: 0 !important;
	margin: 0 !important;
}

.print-format {
	min-height: unset !important;
	max-width: unset !important;
}

.page {
	width: 210mm;
	height: 297mm;
	position: relative;
	overflow: hidden;
	page-break-after: always;
	background-image: url("/assets/connect_diagnostics_core/images/print_formats/cd_purchase_orders.jpg");
	background-size: 210mm 297mm;
	background-repeat: no-repeat;
	font-family: "THSarabun", "Sarabun", Arial, sans-serif;
	font-size: 12pt;
	color: #111;
}

.page:last-child {
	page-break-after: auto;
}

.f {
	position: absolute;
	line-height: 1.08;
	white-space: normal;
}

.field {
	position: absolute;
	line-height: 1.08;
	white-space: nowrap;
}

.text-right {
	text-align: right;
}

.amount {
	text-align: right;
	font-variant-numeric: tabular-nums;
	white-space: nowrap;
}

.tr {
	text-align: right;
}
.tc {
	text-align: center;
}

.nowrap {
	white-space: nowrap;
	overflow: hidden;
}

.small {
	font-size: 10.5pt;
}

.medium {
	font-size: 12pt;
}

.copy-label {
	position: absolute;
	top: 42.5mm;
	right: 33.5mm;
	width: 42mm;
	text-align: center;
	font-size: 15pt;
	z-index: 99;
}

.items table {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}

.items td {
	vertical-align: top;
	line-height: 1.05;
}

.party-name {
	top: 56mm;
	left: 32mm;
	width: 88mm;
}

.company-address {
	top: 80;
	left: 130;
	width: 290;
}

.party-address {
	top: 64mm;
	left: 18mm;
	width: 88mm;
	line-height: 1.12;
}

.party-tax {
	top: 87mm;
	left: 23mm;
	width: 77mm;
}

.doc-no {
	top: 56mm;
	left: 136mm;
	width: 52mm;
}

.doc-date {
	top: 62.3mm;
	left: 125mm;
	width: 65mm;
}

.due-date {
	top: 75mm;
	left: 132mm;
	width: 65mm;
}

.reference {
	top: 94mm;
	left: 18mm;
	width: 80mm;
}

.terms {
	top: 94mm;
	left: 125mm;
	width: 65mm;
}

.items {
	top: 115mm;
	left: 14mm;
	width: 190mm;
}

.col-no {
	width: 10mm;
	text-align: center;
}

.col-desc {
	width: 78mm;
}

.col-wh {
	width: 14mm;
	text-align: center;
}

.col-qty {
	width: 26mm;
	text-align: center;
}

.col-rate {
	width: 26mm;
	text-align: right;
}

.col-amount {
	width: 28mm;
	text-align: right;
}

.po-qty-shift {
	display: inline-block;
	transform: translateX(-7.5mm);
}

.po-rate-shift {
	display: inline-block;
	transform: translateX(-12.8mm);
}

.po-line-amount-shift {
	display: inline-block;
	transform: translateX(-2mm);
}

.remarks {
	top: 225mm;
	left: 18mm;
	width: 82mm;
}

.total {
	top: 228mm;
	left: 170mm;
	width: 31mm;
}

.discount {
	top: 235mm;
	left: 170mm;
	width: 31mm;
}
.vat-rate {
	top: 247mm;
	left: 150mm;
	width: 31mm;
}

.vat {
	top: 247mm;
	left: 170mm;
	width: 31mm;
}

.grand {
	top: 258mm;
	left: 170mm;
	width: 31mm;
	font-weight: 700;
}

html:
{%- macro d(value) -%}
{%- if value -%}
{{ frappe.format_date(value, "dd/MM/yyyy") }}
{%- endif -%}
{%- endmacro -%}

{%- macro money(value) -%}
{{ print_currency(value or 0, currency=doc.get("currency")) }}
{%- endmacro -%}

{%- macro item_name(item) -%}
{{ item.get("item_code") or "" }}
{% if item.get("item_name") and item.get("item_name") != item.get("item_code") %}
 {{ item.get("item_name") }}
{% endif %}
{%- endmacro -%}

{% for copy in [
    {"class": "page-original", "label": "ต้นฉบับ/Original"},
    {"class": "page-copy", "label": "สำเนา/Copy"}
] %}

<div class="page {{ copy.class }}">

    <div class="f company-address medium">
        {{ (doc.get("billing_address_display") or "") }}
    </div>

    <div class="copy-label">
        {{ copy.label }}
    </div>

    <div class="f party-name nowrap">
        {{ doc.get("supplier_name") or doc.get("supplier") or "" }}
    </div>

    <div class="f party-address small">
        {{ (doc.get("address_display") or "") }}
    </div>

    <div class="f party-tax small">
        {{ doc.get("company_tax_id") or "" }}
    </div>

    <div class="f doc-no">
        {{ doc.get("name") }}
    </div>

    <div class="f doc-date">
        {{ d(doc.get("transaction_date")) }}
    </div>

    <div class="f due-date">
        {{ d(doc.get("schedule_date")) }}
    </div>

    <div class="f reference small">
        {{ doc.get("supplier_quotation") or doc.get("order_confirmation_no") or "" }}
    </div>

    <div class="f terms small">
        {{ doc.get("payment_terms_template") or "" }}
    </div>

    <div class="f items">
        <table>
            {%- for item in doc.get("items") or [] -%}
            {%- if loop.index <= 15 -%}
            <tr>
                <td class="col-no">
                    {{ loop.index }}
                </td>
                <td class="col-desc">
                    {{ item_name(item) }}
                </td>
                <td class="col-wh">
                    {{ (item.get("warehouse") or "").split(" - ")[0] }}
                </td>
                <td class="col-qty">
                    <span class="po-qty-shift">
                        {{ "%g"|format(item.get("qty") or 0) }}
                        {{ item.get("uom") or "" }}
                    </span>
                </td>
                <td class="col-rate">
                    <span class="po-rate-shift">
                        {{ print_currency(
                            item.get("rate") or 0,
                            currency=doc.get("currency")
                        ) }}
                    </span>
                </td>
                <td class="col-amount">
                    <span class="po-line-amount-shift">
                        {{ print_currency(
                            item.get("amount") or 0,
                            currency=doc.get("currency")
                        ) }}
                    </span>
                </td>
            </tr>
            {%- endif -%}
            {%- endfor -%}
        </table>
    </div>

    <div class="f remarks small">
        {{ (doc.get("terms") or "") | striptags }}
    </div>

    <div class="f tr total">
        {{ money(doc.get("total")) }}
    </div>

    <div class="f tr discount">
        {{ money(doc.get("discount_amount")) if doc.get("discount_amount") else "-" }}
    </div>
    <div class="f vat-rate"> {{ doc.taxes[0].rate }} %</div>
    <div class="f tr vat">
        {{ money(doc.get("total_taxes_and_charges")) }}
    </div>

    <div class="f tr grand">
        {{ money(doc.get("rounded_total") or doc.get("grand_total")) }}
    </div>

</div>

{% endfor %}
